char *SkipWhitespace( char *data, qboolean *hasNewLines ) { /* <=== SkipWhitespace */ 
	int c;

	while ( ( c = *data ) <= ' ' ) {
		if ( c == '\n' ) {
			com_lines++;
			*hasNewLines = qtrue;
		} else if ( !c )   {
			return NULL;
		}
		data++;
	}

	return data;
}

